const cmds=["template --help","set --help","stamp --help","encode --help","table --help"];
const rs=await Promise.all(cmds.map(s=>tools.exec_command({cmd:`${py} ${runner} response ${s}`,yield_time_ms:30000,max_output_tokens:1200})));
for(let i=0;i<rs.length;i++)text(`--- ${cmds[i]} ---\n${rs[i].output}`);

const out="/Users/johnlee/.local/state/stamped-in-practice/narps-neutral-v1/runs/narps-neutral-r1-08/judgments/narps-neutral-r1-08-j01/attempt-01/judgment";
const py="/Users/johnlee/code/CON/stamped-in-practice/.pixi/envs/default/bin/python";
const runner="/Users/johnlee/code/CON/stamped-in-practice/scripts/assessment.py";
const cmd=`${py} ${runner} response template -o '${out}/2026-10-16-response.json' > '${out}/response-template.stdout' 2> '${out}/response-template.stderr'`;
const r=await tools.exec_command({cmd,yield_time_ms:30000,max_output_tokens:1000});
text(JSON.stringify(r));

const out="/Users/johnlee/.local/state/stamped-in-practice/narps-neutral-v1/runs/narps-neutral-r1-08/judgments/narps-neutral-r1-08-j01/attempt-01/judgment";
const py="/Users/johnlee/code/CON/stamped-in-practice/.pixi/envs/default/bin/python";
const runner="/Users/johnlee/code/CON/stamped-in-practice/scripts/assessment.py";
const response=`${out}/2026-10-16-response.json`;
const items=[
["must/001","met","All supplied project files sit under the workspace root; input, code, results and figures have distinct paths.","judgement",["REPORT.md=Identifies the delivered report, code, results and figure locations"]],
["must/002","met","The participant maps are annex-linked under input/data and their source inventory is inside the same root.","judgement",["input/sources.json=Lists sources, checksums and map paths","input/data/sub-001_hypo1_cope.nii.gz=Captured annex link resolves within the project root"]],
["must/003","unmet","The script imports external Python packages, but the delivery has no environment declaration or linked software module.","judgement",["analysis.py=Imports NumPy, pandas, nibabel, nilearn, SciPy and matplotlib","probe:env-spec-tracked=No tracked environment specification or software module"]],
["must/004","partial","Git is used, but the report, analysis script, figures and results were untracked at worker stop.","probe:tree-clean",["probe:tree-clean=Worker-stop Git status lists the scientific deliverables as untracked","REPORT.md=Complete scientific report present in stopped delivery"]],
["must/005","met","Git-annex carries the 54 participant maps; the stop capture includes their bytes and mapping.","probe:large-in-annex",["probe:large-in-annex=54 annex pointers; no large binary blobs in Git","input/sources.json=Map byte sizes and SHA-256 values"]],
["must/006","unmet","No run record links the shipped results to an exact environment specification; none is included in the delivery.","probe:run-env-linked",["probe:run-env-linked=No run records identify an environment","probe:env-spec-tracked=No environment specification in the complete delivery"]],
["must/007","partial","REPORT.md gives a usage pointer to analysis.py but does not provide installation or dependency setup instructions.","probe:entry-point+judgement",["REPORT.md=Reproducibility files section says to run analysis.py with a supplied Python environment","probe:entry-point=No README or Makefile with install/usage instructions"]],
["must/008","met","analysis.py is a clear starting point and REPORT.md identifies it as the complete group workflow.","probe:entry-point+judgement",["analysis.py=Documented complete group workflow","REPORT.md=Reproducibility files section"]],
["must/009","met","The analysis script derives input and output paths from its own location with pathlib.","probe:no-abs-paths",["analysis.py=ROOT-relative paths for inputs, results and figures","probe:no-abs-paths=No host-specific absolute paths in tracked text"]],
["must/010","unmet","NumPy, pandas, nibabel, nilearn, SciPy and matplotlib are imported without any delivered environment specification.","probe:env-spec-tracked",["analysis.py=External package imports","probe:env-spec-tracked=No environment specification"]],
["must/011","unmet","The report assumes a supplied Python environment but does not identify its platform, Python version or required host configuration.","judgement",["REPORT.md=Run instruction refers to a supplied Python environment without documenting its contents","analysis.py=Requires Python and external scientific packages"]],
["must/012","unmet","No delivered documentation or environment file lists the system requirements and dependencies needed to run analysis.py.","probe:env-spec-tracked",["REPORT.md=No dependency list in reproducibility instructions","probe:env-spec-tracked=No tracked environment specification"]],
["must/013","unmet","No environment specification is present in the worker's captured workspace or tracked repository.","probe:env-spec-tracked",["probe:env-spec-tracked=No tracked lockfile, container definition or registration"]],
["must/014","unmet","The delivery declares no process for updating environment specifications when dependencies change.","judgement",["REPORT.md=No environment update or lockfile regeneration process","probe:env-spec-tracked=No environment specification"]],
["must/015","unmet","No frozen package manifest, container digest or other exact environment specification is supplied.","probe:env-spec-tracked",["probe:env-spec-tracked=No tracked environment specification","worker-end-state.json=Complete worker-stop capture with no omissions"]],
